def transforms(S):
  out=[]
  for k in range(8):
    pts=[]
    for r,c in S:
      if k>=4: c=-c
      for _ in range(k%4): r,c=c,-r
      pts.append((r,c))
    mr=min(r for r,c in pts); mc=min(c for r,c in pts)
    out.append({(r-mr,c-mc) for r,c in pts})
  # unique
  ans=[]
  for t in out:
    if t not in ans: ans.append(t)
  return ans
for name,obj in objs.items():
  matches=[]
  for i,t in enumerate(transforms(S)):
    for ar in range(min(r for r,c in obj)-4,max(r for r,c in obj)+2):
      for ac in range(min(c for r,c in obj)-4,max(c for r,c in obj)+2):
        placed={(ar+r,ac+c) for r,c in t}
        if obj<=placed: matches.append((i,ar,ac,placed))
  print(name, [(i,r,c) for i,r,c,_ in matches])

