import sqlite3,collections
p='/home/ubuntu/continual-arc-baselines/.workbench/runs/adhoc-hermesagentlearner-1790682293/attempts/f7caca328fe8413b9d0d460bc3931015/system/state/hermes/state.db'; c=sqlite3.connect(p); s=c.execute('select content from messages where id=6302').fetchone()[0]
part=s.split('Test input (30x30):',1)[1].split('Wrong attempts',1)[0]; g=[[int(x) for x in ln.split()] for ln in part.strip().splitlines()]
M={(0,2),(1,1),(1,3),(2,0),(2,1),(2,3)}
def norm(points):
    mr=min(r for r,col in points); mc=min(col for r,col in points); return frozenset((r-mr,col-mc) for r,col in points)
def variants(mask):
    out=[]
    for refl in (False,True):
      for rot in range(4):
        pts=[]
        for r,col in mask:
          x,y=(r,-col) if refl else (r,col)
          for _ in range(rot): x,y=y,-x
          pts.append((x,y))
        m=norm(pts)
        if m not in [v[1] for v in out]: out.append((f'{"F" if refl else "N"}{rot*90}',m))
    return out
# 8-neighbor components of each foreground color
coords_by=collections.defaultdict(set)
for r,row in enumerate(g):
  for col,v in enumerate(row):
    if v!=1: coords_by[v].add((r,col))
def comps(cells):
  rem=set(cells); result=[]
  while rem:
    stack=[rem.pop()]; cc=set(stack)
    while stack:
      r,col=stack.pop()
      for dr in (-1,0,1):
       for dc in (-1,0,1):
        q=(r+dr,col+dc)
        if q in rem: rem.remove(q);cc.add(q);stack.append(q)
    result.append(cc)
  return result
print('orientation label: N0 is original; F means mirror left/right then rotate clockwise')
for color,cells in sorted(coords_by.items()):
  if color==4: continue
  for j,cl in enumerate(comps(cells),1):
    vals=[]
    for label,m in variants(M):
      h=max((sum((r-ar,col-ac) in m for r,col in cl) for ar in range(30) for ac in range(30)),default=0)
      anchors=[(ar,ac) for ar in range(30) for ac in range(30) if sum((r-ar,col-ac) in m for r,col in cl)==h]
      vals.append((label,h,anchors[:4]))
    print('color',color,'component',j,'cells',sorted(cl),'by orientation:',vals)

