cmd = """python3 - <<'PY'
from itertools import product
T={(0,2),(1,1),(1,3),(2,0),(2,1),(2,3)}
def transforms(S):
 out={}
 for k in range(4):
  for refl in range(2):
   pts=set()
   for r,c in S:
    if refl: c=-c
    for _ in range(k): r,c=c,-r
    pts.add((r,c))
   mn_r=min(r for r,c in pts); mn_c=min(c for r,c in pts)
   norm=frozenset((r-mn_r,c-mn_c) for r,c in pts)
   out[norm]=('R'+str(k*90)+('F' if refl else ''))
 return [(name,shape) for shape,name in out.items()]
Ts=transforms(T)
frags={'8':{(1,23),(2,22),(3,22)},'2top':{(3,13),(4,12),(5,11)},'5':{(9,25),(10,24),(10,25)},'6':{(11,5),(12,5),(12,7)},'3':{(11,15),(12,16),(13,16)},'7':{(19,11),(20,12)},'2bottom':{(21,21),(21,22)},'9':{(22,5),(23,3)}}
for name,F in frags.items():
 ans=[]
 for shape,ori in Ts:
  for fr in range(min(r for r,c in F)-3,max(r for r,c in F)+1):
   for fc in range(min(c for r,c in F)-5,max(c for r,c in F)+1):
    Q={(fr+r,fc+c) for r,c in shape}
    if F<=Q: ans.append((ori,(fr,fc),sorted(Q-F)))
 print(name,'candidates',len(ans))
 for x in ans: print(' ',x)
PY"""
